function refreshMidiInputs(){const select=$('midiInput'),prior=select.value;select.replaceChildren(new Option('NO INPUT',''));const output=$('midiOutput'),priorOut=output.value;output.replaceChildren(new Option('NO OUTPUT',''));if(!midiAccess){select.disabled=true;output.disabled=true;$('sendSyx').disabled=true;return;}for(const input of midiAccess.inputs.values())select.add(new Option(input.name||`MIDI ${input.id}`,input.id));const outputs=midiAccess.outputs?[...midiAccess.outputs.values()]:[];for(const port of outputs)output.add(new Option(port.name||`MIDI ${port.id}`,port.id));select.disabled=false;if([...midiAccess.inputs.keys()].includes(prior))select.value=prior;else if(select.children.length===2)select.value=select.children[1].value;else select.value='';selectMidiInput();output.disabled=!outputs.length;if(outputs.some(p=>p.id===priorOut))output.value=priorOut;else if(output.children.length===2)output.value=output.children[1].value;else output.value='';selectMidiOutput();}
