function selectMidiOutput(){midiOut=null;const id=$('midiOutput').value;if(midiAccess&&id)midiOut=midiAccess.outputs?.get(id)||null;$('sendSyx').disabled=!midiSysex||!midiOut;}
function onMidi(event){const m=parseMidiMessage(event.data);if(!m)return;if(m.type==='sysex'){if(isEtchSysex(m.data))void receiveTransfer(m.data,'MIDI');return;}if(['clock','start','continue','stop'].includes(m.type)){handleClock(m,event);return;}if(!midiChannelAccepted(m))return;const id=`midi:${m.channel}:${m.note}`;if(m.type==='on'){if(midiDeferred.delete(id))noteOff(id);noteOn(id,m.note,m.velocity);return;}if(m.type==='off'){if(midiSustain&&active.has(id))midiDeferred.add(id);else noteOff(id);return;}if(m.type==='bend'){send({type:'bend',value:m.value});return;}if(m.type==='sustain'){midiSustain=m.down;if(!m.down){for(const held of [...midiDeferred]){midiDeferred.delete(held);noteOff(held);}}return;}if(m.type==='cc'){applyMappedCC(m);return;}if(m.type==='panic')panic();}
